"""Planar push primitives for the right ARX X5 arm using the closed gripper's side face."""
import numpy as np
from scipy.spatial.transform import Rotation
from shapely.geometry import Polygon
import scene

# nominal gripper geometry (controlled-point frame, metres)
FACE_CENTER_ALONG_A = 0.5*(0.07157+0.15757)   # centre of the pushing face along approach
FINGER_OUTER_AT_ZERO = 0.03775                # local-Y of finger_1 outer face at zero displacement
FINGER_DISP_FULL_OPEN = 0.044

def face_offset(opening_norm):
    """Local-Y offset of finger_1's outer (pushing) face for a normalised opening."""
    return FINGER_OUTER_AT_ZERO + FINGER_DISP_FULL_OPEN*float(opening_norm)

def block_state(obs):
    S = scene.seg(obs)
    reg = scene.register(S["Pb_top"][:,:2], S["Pp"][:,:2])
    bpoly = Polygon(reg["src_contour"]).simplify(0.002)
    ppoly = Polygon(reg["dst_contour"]).simplify(0.002)
    return S, reg, bpoly, ppoly

def alignment(reg, bpoly, ppoly):
    c_b = np.array(bpoly.centroid.coords[0]); c_p = np.array(ppoly.centroid.coords[0])
    return {"theta_deg": float(np.degrees(reg["theta_rad"])), "dc": c_p-c_b,
            "c_block": c_b, "c_pad": c_p, "rms": reg["rms"]}

def verts(poly):
    return np.array([np.array(v) for v in list(poly.exterior.coords)[:-1]])

def make_push(bv, d_deg, gap, travel, z, foff, a_sign=1, q=None):
    """Face-push: flat finger side face, outward normal along d, contact at the support point."""
    a_rad = np.deg2rad(d_deg)
    d = np.array([np.cos(a_rad), np.sin(a_rad), 0.0])
    proj = bv @ d[:2]
    if q is None:
        q = bv[int(np.argmin(proj))]
    q = np.asarray(q, float)[:2]
    a = np.array([-d[1], d[0], 0.0])*a_sign
    sd = float(q @ d[:2]); sa = float(q @ a[:2])
    p = d*(sd + gap - foff) + a*(sa - FACE_CENTER_ALONG_A)
    p[2] = z
    M = np.stack([a, d, np.cross(a, d)], axis=1)
    quat = Rotation.from_matrix(M).as_quat()
    return {"d": d, "a": a, "q": q, "p_start": p, "p_end": p + travel*d,
            "quat": quat, "M": M, "proj_q": sd}

def pose7(p, quat):
    return [float(p[0]), float(p[1]), float(p[2]), float(quat[0]), float(quat[1]), float(quat[2]), float(quat[3])]

def world_dir(v):
    return [float(v[0]), float(v[1]), float(v[2])]

