import numpy as np
from ctl2 import *
import ctl2 as K2
from runpush import escape_home, plan_and_push
foff = C.face_off()
def do(al, verts, smax, tag):
    c = al["c_block"].copy(); th = al["theta_deg"]; dc = al["dc"]
    pl = C.plan_general(verts, c, dc, th, C.load_gains(), s_max=smax)
    if pl is None:
        print("  no plan"); return None, None
    print("  %s d=%.0f tau %+.2f cosb %.2f s %.3f (theta %.1f dc %s)" % (
        tag, pl["d_deg"], pl["tau"], pl["cosb"], pl["s"], th, np.round(dc,4)))
    return plan_and_push(verts, c, pl["d"], pl["s"], foff, tag=tag), c
al, verts, ok = measure("STATE")
if not ok: handoff("measure unreliable", theta=al["theta_deg"])
rr, c = do(al, verts, 0.014, "T0")
if rr is None: handoff("push failed")
if escape_home(c) is None: print(" escape incomplete")
al2, v2, ok2 = measure(" after T0")
if not ok2: handoff("measure unreliable after push", theta=al2["theta_deg"])
print("    RESP dth %+.2f dc %s" % (al2["theta_deg"]-al["theta_deg"], np.round(al2["c_block"]-c,4)))
rr2, c2 = do(al2, v2, 0.014, "T1")
if rr2 is not None:
    if escape_home(c2) is None: print(" escape2 incomplete")
    al3, v3, ok3 = measure(" after T1")
    if ok3:
        print("    RESP dth %+.2f dc %s" % (al3["theta_deg"]-al2["theta_deg"], np.round(al3["c_block"]-c2,4)))
        al2 = al3
print("FINAL theta %.2f dc %s" % (al2["theta_deg"], np.round(al2["dc"],4)))
